import random, json, sys
sys.path.insert(0, '/app')
from language import StaticError, InvalidProgram
from checker import check
from interpreter import run

KINDS = ['int','text','bool','unit']

def rand_val(k, rng):
    if k=='int': return rng.randint(-3,3)
    if k=='text': return rng.choice(['','a','xy','foo'])
    if k=='bool': return rng.choice([True,False])
    return None

class Gen:
    """Random program generator, roughly type-aware to boost checker acceptance."""
    def __init__(self, rng, cells, inputs):
        self.rng = rng
        self.cells = cells      # name -> set of kinds
        self.inputs = inputs    # name -> kind
        self.node_budget = [400]

    def lit(self, k):
        return ["lit", rand_val(k, self.rng)]

    # generate an expression of a desired scalar kind, possibly with effects
    def expr_scalar(self, k, env, depth, risky=False):
        rng = self.rng
        if depth > 5 or self.node_budget[0] <= 0:
            return self.lit(k)
        self.node_budget[0] -= 1
        options = ['lit','lit','var','get','binop','call_fn_returning']
        if risky: options += ['var','get']
        op = rng.choice(options)
        if op=='lit':
            return self.lit(k)
        if op=='var':
            cands = [n for n,t in env.items() if t==k] + [n for n,t in self.inputs.items() if t==k]
            if cands: return ["var", rng.choice(cands)]
            return self.lit(k)
        if op=='get':
            cands = [n for n,ts in self.cells.items() if ts=={k}]
            if cands: return ["get", rng.choice(cands)]
            return self.lit(k)
        if op=='binop':
            if k=='int':
                if rng.random()<0.5:
                    return ["add", self.expr_scalar('int',env,depth+1), self.expr_scalar('int',env,depth+1)]
                else:
                    return self.lit(k)
            if k=='text':
                return ["cat", self.expr_scalar('text',env,depth+1), self.expr_scalar('text',env,depth+1)]
            if k=='bool':
                c = rng.choice(['not','lt','is'])
                if c=='not': return ["not", self.expr_scalar('bool',env,depth+1)]
                if c=='lt': return ["lt", self.expr_scalar('int',env,depth+1), self.expr_scalar('int',env,depth+1)]
                cands = list(self.cells)
                if cands and rng.random()<0.8:
                    return ["is", rng.choice(cands), rng.choice(KINDS)]
                return self.lit('bool')
            return self.lit(k)
        if op=='call_fn_returning':
            fns = [n for n,t in env.items() if isinstance(t,tuple) and t[0]=='fn' and t[1]==k]
            if fns:
                return ["call", ["var", rng.choice(fns)]]
            return self.lit(k)
        return self.lit(k)

    # random function expression returning kind k, writing random cells
    def fn_expr(self, k, env, depth):
        rng = self.rng
        writes = rng.sample(list(self.cells), rng.randint(0, min(2,len(self.cells)))) if self.cells else []
        body = []
        inner_env = dict(env)
        for w in writes:
            wk = rng.choice(sorted(self.cells[w]))
            body.append(["set", w, self.expr_scalar(wk, inner_env, depth+1)])
        # sometimes conditional writes
        if self.cells and rng.random()<0.5:
            c = rng.choice(list(self.cells)); kk = rng.choice(KINDS)
            then_b = []
            if rng.random()<0.7:
                tcell = rng.choice(list(self.cells))
                tk = rng.choice(sorted(self.cells[tcell]))
                then_b.append(["set", tcell, self.expr_scalar(tk, inner_env, depth+1)])
            body.append(["if", ["is", c, kk], then_b, []])
        result = self.expr_scalar(k, inner_env, depth+1)
        return ("fn", k, ["fn", body, result])

    def block(self, env, depth, length):
        rng = self.rng
        stmts = []
        for _ in range(length):
            if self.node_budget[0] <= 0: break
            self.node_budget[0] -= 1
            op = rng.choice(['let','letfn','set','eval','if','repeat','callfn','assignfn'] +
                            ['eval','set'])
            if op=='let':
                k = rng.choice(KINDS)
                n = "v%d" % rng.randint(0,999)
                while n in env or n in self.cells or n in self.inputs:
                    n = "v%d" % rng.randint(0,999)
                stmts.append(["let", n, self.expr_scalar(k, env, depth+1)])
                env[n] = k
            elif op=='letfn':
                k = rng.choice(KINDS)
                n = "f%d" % rng.randint(0,999)
                while n in env or n in self.cells or n in self.inputs:
                    n = "f%d" % rng.randint(0,999)
                f = self.fn_expr(k, env, depth+1)
                stmts.append(["let", n, f[2]])
                env[n] = ('fn', k)
            elif op=='assignfn':
                fns = [n for n,t in env.items() if isinstance(t,tuple) and t[0]=='fn']
                if fns:
                    n = rng.choice(fns); k = env[n][1]
                    f = self.fn_expr(k, env, depth+1)
                    stmts.append(["assign", n, f[2]])
                else:
                    stmts.append(["eval", self.expr_scalar('int', env, depth+1)])
            elif op=='set':
                if not self.cells: continue
                c = rng.choice(list(self.cells))
                k = rng.choice(sorted(self.cells[c]))
                stmts.append(["set", c, self.expr_scalar(k, env, depth+1)])
            elif op=='eval':
                k = rng.choice(KINDS)
                stmts.append(["eval", self.expr_scalar(k, env, depth+1)])
            elif op=='callfn':
                fns = [n for n,t in env.items() if isinstance(t,tuple) and t[0]=='fn']
                if fns:
                    stmts.append(["eval", ["call", ["var", rng.choice(fns)]]])
                else:
                    stmts.append(["eval", self.expr_scalar('int', env, depth+1)])
            elif op=='if':
                cond = self.expr_scalar('bool', env, depth+1)
                then_env = dict(env); else_env = dict(env)
                then_b = self.block(then_env, depth+1, rng.randint(0,3))
                else_b = self.block(else_env, depth+1, rng.randint(0,3))
                stmts.append(["if", cond, then_b, else_b])
                # crude merge: keep only common keys
                env.clear()
                for n in then_env:
                    if n in else_env and then_env[n]==else_env[n]:
                        env[n]=then_env[n]
            elif op=='repeat':
                cnt = self.expr_scalar('int', env, depth+1)
                loop_env = dict(env)
                b = self.block(loop_env, depth+1, rng.randint(1,3))
                stmts.append(["repeat", cnt, b])
            if len(stmts) >= 120: break
        return stmts

def gen_program(rng):
    ncells = rng.randint(1,3)
    cells = {}
    for i in range(ncells):
        ts = rng.sample(KINDS, rng.randint(1,2))
        # bias toward multi-kind
        if rng.random()<0.5 and len(ts)<2: ts.append(rng.choice(KINDS)); ts=list(set(ts))
        cells["c%d"%i] = {"types": ts, "value": rand_val(ts[0], rng)}
    inputs = {}
    if rng.random()<0.4:
        inputs["in0"] = rand_val(rng.choice(KINDS), rng)
    g = Gen(rng, {n:set(d["types"]) for n,d in cells.items()}, {n:None for n in inputs})
    # fix inputs map kind
    g.inputs = {}
    for n,v in inputs.items():
        kk = 'unit' if v is None else 'bool' if type(v) is bool else 'int' if type(v) is int else 'text'
        g.inputs[n]=kk
    env = dict(g.inputs)
    body = g.block(env, 0, rng.randint(2,10))
    # often end with a cell read op that could error
    if cells and rng.random()<0.6:
        c = rng.choice(list(cells))
        body.append(["eval", ["add", ["get", c], ["lit",1]]])
    return {"cells": cells, "inputs": inputs, "body": body}

def main():
    seed = int(sys.argv[1]) if len(sys.argv)>1 else 0
    rng = random.Random(seed)
    n = 0; acc = 0
    for i in range(200000):
        p = gen_program(rng)
        n += 1
        try:
            check(p)
        except StaticError:
            continue
        except Exception as e:
            continue
        acc += 1
        r = run(p)
        if r['status'] == 'type_error':
            print("FOUND seed", seed, "iter", i)
            print(json.dumps(p))
            with open('/tmp/fuzz/found.json','w') as f:
                json.dump(p,f)
            return
        if r['status'] not in ('normal','step_limit'):
            print("OTHER", r['status'], json.dumps(p)[:400])
    print(f"done: {n} generated, {acc} accepted, no type_error found")

