        if depth>=6:
            return ["lit", rand_val(rng.choice(KINDS),rng)]
        op = rng.choice(['lit','var','get','is','add','cat','lt','not','fn','call',
                         'lit','get','add','is','call','fn'])
        if op=='lit': return ["lit", rand_val(rng.choice(KINDS),rng)]
        if op=='var':
            names=self.inputs+[n for sc in self.locals for n in sc]
            if names and rng.random()<0.9: return ["var", rng.choice(names)]
            return ["lit", rand_val(rng.choice(KINDS),rng)]
        if op=='get':
            if self.cells: return ["get", rng.choice(self.cells)]
            return ["lit", rand_val(rng.choice(KINDS),rng)]
        if op=='is':
            if self.cells: return ["is", rng.choice(self.cells), rng.choice(KINDS)]
            return ["lit", True]
        if op in ('add','cat','lt'):
            return [op, self.expr(depth+1), self.expr(depth+1)]
        if op=='not': return ["not", self.expr(depth+1)]
        if op=='fn':
            self.locals.append([])
            body=self.block(depth+1, rng.randint(0,3))
            res=self.expr(depth+1)
            self.locals.pop()
            return ["fn", body, res]
        if op=='call':
            return ["call", self.expr(depth+1)]
    def stmt(self, depth):
        rng=self.rng
        op = rng.choice(['let','assign','set','eval','if','repeat','set','eval','let'])
        if op=='let':
            n="v%d"%rng.randint(0,50)
            s=["let",n,self.expr(depth+1)]
            if self.locals is not None and self.locals:
                self.locals[-1].append(n)
            elif self.locals is not None:
                self.locals.append([n])
            return s
        if op=='assign':
            names=[n for sc in self.locals for n in sc if n not in self.inputs]
            if names: return ["assign", rng.choice(names), self.expr(depth+1)]
            return ["eval", self.expr(depth+1)]
        if op=='set':
            if self.cells: return ["set", rng.choice(self.cells), self.expr(depth+1)]
            return ["eval", self.expr(depth+1)]
        if op=='eval': return ["eval", self.expr(depth+1)]
        if op=='if':
            self.locals.append([])
            tb=self.block(depth+1,rng.randint(0,3))
            self.locals.pop()
            self.locals.append([])
            eb=self.block(depth+1,rng.randint(0,3))
            self.locals.pop()
            return ["if", self.expr(depth+1), tb, eb]
        if op=='repeat':
            self.locals.append([])
            b=self.block(depth+1,rng.randint(1,3))
            self.locals.pop()
            return ["repeat", self.expr(depth+1), b]
    def block(self, depth, n):
        return [self.stmt(depth) for _ in range(n)]

def gen(rng):
    ncells=rng.randint(1,3)
    cells={}
    for i in range(ncells):
        ts=list(set(rng.sample(KINDS, rng.choice([1,2,2,3]))))
        cells["c%d"%i]={"types":ts,"value":rand_val(ts[0],rng)}
    inputs={}
    if rng.random()<0.3: inputs["i0"]=rand_val(rng.choice(KINDS),rng)
    g=RawGen(rng,list(cells),list(inputs))
    g.locals.append([])
    body=g.block(0,rng.randint(2,9))
    return {"cells":cells,"inputs":inputs,"body":body}

def main():
    seed=int(sys.argv[1]) if len(sys.argv)>1 else 0
    rng=random.Random(seed)
    n=acc=0
    for i in range(300000):
        p=gen(rng); n+=1
        try:
            check(p)
        except StaticError:
            continue
        except Exception:
            continue
        acc+=1
        r=run(p)
        if r['status']=='type_error':
            print("FOUND seed",seed,"iter",i,"steps",r['steps'],r.get('message'))
            print(json.dumps(p))
            with open('/tmp/fuzz/found.json','w') as f: json.dump(p,f)
            return
        elif r['status']=='other_runtime_error':
            pass
    print(f"done seed={seed}: {n} gen, {acc} accepted, none")

main()
